<?php
declare(strict_types=1); namespace PWT\Staff\Admin; defined('ABSPATH')||exit; use PWT\Staff\CRM\FollowUpRepository; use PWT\Staff\CRM\FeedbackRepository; use PWT\Staff\CRM\ComplaintRepository;
final class CRMControlCentre { public function __construct(private FollowUpRepository $followups,private FeedbackRepository $feedback,private ComplaintRepository $complaints){} public function register():void{add_action('admin_menu',[$this,'menu'],45);} public function menu():void{add_submenu_page('pwt-staff-dashboard','CRM Control Centre','CRM Control Centre','pwt_access_staff_dashboard','pwt-crm-control-centre',[$this,'render']);} public function render():void{if(!current_user_can('pwt_access_staff_dashboard'))wp_die('Not allowed');$f=count(get_posts(['post_type'=>FeedbackRepository::POST_TYPE,'numberposts'=>-1]));$c=count(get_posts(['post_type'=>ComplaintRepository::POST_TYPE,'numberposts'=>-1]));$fu=count($this->followups->due());echo '<div class="wrap"><h1>Customer CRM Control Centre</h1><div class="pwt-admin-cards"><div class="pwt-admin-card"><strong>Follow-ups Open</strong><span>'.esc_html((string)$fu).'</span></div><div class="pwt-admin-card"><strong>Feedback Records</strong><span>'.esc_html((string)$f).'</span></div><div class="pwt-admin-card"><strong>Complaints</strong><span>'.esc_html((string)$c).'</span></div></div><p>Use customer records, booking history, follow-ups and communications to maintain a complete customer relationship timeline.</p></div>';}}
